import firebase_admin
from firebase_admin import credentials, auth
import os

FIREBASE_PROJECT_ID = os.environ.get("FIREBASE_PROJECT_ID")

def initialize_firebase_app():
    if not firebase_admin._apps:
        cred = credentials.ApplicationDefault()
        firebase_admin.initialize_app(cred, {"projectId": FIREBASE_PROJECT_ID})
    return firebase_admin.get_app()

def get_firebase_auth_client():
    app = initialize_firebase_app()
    return auth

import requests
import os

FIREBASE_WEB_API_KEY = os.environ.get("FIREBASE_WEB_API_KEY")

def email_password_login(payload):
    rest_api_url = f"https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key={FIREBASE_WEB_API_KEY}"
    headers = {"Content-Type": "application/json"}
    data = {
        "email": payload.email,
        "password": payload.password,
        "returnSecureToken": True
    }
    response = requests.post(rest_api_url, json=data, headers=headers)
    response.raise_for_status()
    return response.json()

import requests
import os

FIREBASE_WEB_API_KEY = os.environ.get("FIREBASE_WEB_API_KEY")

def refresh_session(payload):
    rest_api_url = f"https://securetoken.googleapis.com/v1/token?key={FIREBASE_WEB_API_KEY}"
    headers = {"Content-Type": "application/json"}
    data = {
        "grant_type": "refresh_token",
        "refresh_token": payload.refresh_token
    }
    response = requests.post(rest_api_url, json=data, headers=headers)
    response.raise_for_status()
    return response.json()

import requests
import os

FIREBASE_WEB_API_KEY = os.environ.get("FIREBASE_WEB_API_KEY")

def password_reset(payload):
    rest_api_url = f"https://identitytoolkit.googleapis.com/v1/accounts:sendOobCode?key={FIREBASE_WEB_API_KEY}"
    headers = {"Content-Type": "application/json"}
    data = {
        "requestType": "PASSWORD_RESET",
        "email": payload.email
    }
    response = requests.post(rest_api_url, json=data, headers=headers)
    response.raise_for_status()
    return response.json()
